diff --git a/src/applet/devicesproxymodel.cpp b/src/applet/devicesproxymodel.cpp
index bea49e5c..38b9efcb 100644
--- a/src/applet/devicesproxymodel.cpp
+++ b/src/applet/devicesproxymodel.cpp
@@ -7,7 +7,9 @@
 #include "devicesproxymodel.h"
 #include "utils.h"

+#include <KConfigGroup>
 #include <KLocalizedString>
+#include <KSharedConfig>

 #include <BluezQt/Adapter>
 #include <BluezQt/Device>
@@ -16,9 +18,30 @@ DevicesProxyModel::DevicesProxyModel(QObject *parent)
     : QSortFilterProxyModel(parent)
 {
     setDynamicSortFilter(true);
+
+    m_configWatcher = KConfigWatcher::create(KSharedConfig::openConfig(QStringLiteral("bluedevilglobalrc")));
+    connect(m_configWatcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group) {
+        if (group.name() == QLatin1String("LastConnected")) {
+            loadLastConnected();
+            invalidate();
+        }
+    });
+    loadLastConnected();
+
     sort(0, Qt::DescendingOrder);
 }

+void DevicesProxyModel::loadLastConnected()
+{
+    const KConfigGroup group = m_configWatcher->config()->group(QStringLiteral("LastConnected"));
+
+    m_lastConnected.clear();
+    const QStringList addresses = group.keyList();
+    for (const QString &address : addresses) {
+        m_lastConnected.insert(address, group.readEntry(address, QDateTime()));
+    }
+}
+
 bool DevicesProxyModel::hideBlockedDevices() const
 {
     return m_hideBlockedDevices;
@@ -107,6 +130,17 @@ bool DevicesProxyModel::lessThan(const QModelIndex &left, const QModelIndex &rig
         return false;
     }

+    // Most recently used go above the ones used longer ago or never
+    const QDateTime leftLastConnected = m_lastConnected.value(left.data(BluezQt::DevicesModel::AddressRole).toString());
+    const QDateTime rightLastConnected = m_lastConnected.value(right.data(BluezQt::DevicesModel::AddressRole).toString());
+
+    if (leftLastConnected != rightLastConnected) {
+        if (!leftLastConnected.isValid() || !rightLastConnected.isValid()) {
+            return !leftLastConnected.isValid();
+        }
+        return leftLastConnected < rightLastConnected;
+    }
+
     const QString &leftName = left.data(BluezQt::DevicesModel::NameRole).toString();
     const QString &rightName = right.data(BluezQt::DevicesModel::NameRole).toString();

diff --git a/src/applet/devicesproxymodel.h b/src/applet/devicesproxymodel.h
index 7810e748..79e8e90e 100644
