+#include <QDateTime>
 #include <QSortFilterProxyModel>

 #include <qqmlregistration.h>
@@ -45,7 +47,10 @@ Q_SIGNALS:

 private:
     bool duplicateIndexAddress(const QModelIndex &idx) const;
+    void loadLastConnected();

     bool m_hideBlockedDevices = false;
     bool m_unpairedOnly = false;
+    KConfigWatcher::Ptr m_configWatcher;
+    QHash<QString, QDateTime> m_lastConnected;
 };
diff --git a/src/kded/devicemonitor.cpp b/src/kded/devicemonitor.cpp
index 1de54443..b3fb9b37 100644
--- a/src/kded/devicemonitor.cpp
+++ b/src/kded/devicemonitor.cpp
@@ -10,6 +10,7 @@
 #include "bluedevildaemon.h"
 #include "bluedevilglobalsettings.h"

+#include <QDateTime>
 #include <QTimer>

 #include <KConfigGroup>
@@ -129,6 +130,10 @@ void DeviceMonitor::deviceAdded(BluezQt::DevicePtr device)
     updateDevicePlace(device);
     org::kde::KDirNotify::emitFilesAdded(QUrl(QStringLiteral("bluetooth:/")));

+    if (device->isConnected()) {
+        saveLastConnected(device);
+    }
+
     connect(device.data(), &BluezQt::Device::connectedChanged, this, &DeviceMonitor::deviceConnectedChanged);
 }

@@ -139,6 +144,19 @@ void DeviceMonitor::deviceConnectedChanged(bool connected)

     BluezQt::DevicePtr device = static_cast<BluezQt::Device *>(sender())->toSharedPtr();
     updateDevicePlace(device);
+    saveLastConnected(device);
+}
+
+void DeviceMonitor::saveLastConnected(BluezQt::DevicePtr device)
+{
+    if (!device->isPaired()) {
+        return;
+    }
+
+    // Written on connect and on disconnect, so it is the last time the device was in use
+    KConfigGroup group = GlobalSettings::self()->config()->group(QStringLiteral("LastConnected"));
+    group.writeEntry(device->address(), QDateTime::currentDateTimeUtc(), KConfig::Notify);
+    group.sync();
 }

 void DeviceMonitor::login1PrepareForSleep(bool active)
diff --git a/src/kded/devicemonitor.h b/src/kded/devicemonitor.h
index 039e8a8c..d45a0025 100644
--- a/src/kded/devicemonitor.h
+++ b/src/kded/devicemonitor.h
@@ -42,6 +42,7 @@ private:

     void clearPlaces();
     void updateDevicePlace(BluezQt::DevicePtr device);
+    void saveLastConnected(BluezQt::DevicePtr device);

     KFilePlacesModel *places();

